function applyRoleVisibility(){const form=el('form'),showField=(name,show)=>{const field=form?.elements[name]?.closest('.field');if(field)field.style.display=show?'':'none'};showField('category',hasPermission('alterar_status'));showField('priority',hasPermission('classificar_prioridade'));['responsible','status','deadline','next'].forEach(name=>showField(name,hasPermission('alterar_status')));document.querySelectorAll('[data-new]').forEach(x=>x.style.display=canCreateAny()?'':'none');const newNav=document.querySelector('.nav[data-view="nova"]');if(newNav)newNav.style.display=canCreateAny()?'':'none';const usersNav=el('usersNav');if(usersNav)usersNav.style.display=canManage()?'':'none';if(el('reportsNav'))el('reportsNav').style.display=hasPermission('emitir_relatorios')?'':'none';if(el('organizationNav'))el('organizationNav').style.display=isAdmin()?'':'none';const remove=el('deleteDemandButton');if(remove)remove.style.display=editingId!==null&&hasPermission('apagar_demanda')?'':'none';refreshDemandTypeOptions()}
function refreshDemandTypeOptions(){const select=el('demandType');if(!select)return;const currentDemand=demands.find(d=>Number(d.id)===Number(editingId)),current=select.value,allowed=Object.entries(DEMAND_TYPES).filter(([type])=>hasPermission(`criar_${type}`)||currentDemand?.type===type);select.innerHTML=allowed.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');if(allowed.some(([value])=>value===current))select.value=current;configureDemandType()}
function configureDemandType(){const type=el('demandType')?.value||'corretiva',scheduled=['agendamento','preventiva'].includes(type),appointment=type==='agendamento',preventive=type==='preventiva',corrective=type==='corretiva',form=el('form'),field=name=>form?.elements[name]?.closest('.field'),label=(name,text)=>{const x=field(name)?.querySelector('label');if(x)x.textContent=text};const title=form?.elements.title,notes=form?.elements.notes,status=form?.elements.status;title.required=true;notes.required=!appointment;field('title').style.display='';field('notes').style.display='';label('title','Tipo *');label('notes',appointment?'Observações':preventive?'Descrição *':'Descrição do problema *');['scheduleDateField','companyField'].forEach(id=>el(id).style.display=scheduled?'':'none');el('scheduleDate').type=appointment?'datetime-local':'date';el('scheduleDate').required=scheduled;el('companyName').required=scheduled;el('scheduleDateField').querySelector('label').textContent=appointment?'Data e horário prevista *':'Data prevista *';el('companyField').querySelector('label').textContent=appointment?'Prestador *':'Responsável pela execução *';el('additionalNotesField').style.display=preventive?'':'none';el('additionalNotes').required=false;['category','next'].forEach(name=>{if(field(name))field(name).style.display='none'});['responsible','deadline'].forEach(name=>{if(field(name))field(name).style.display=corrective&&hasPermission('alterar_status')?'':'none'});field('priority').style.display=corrective&&hasPermission('classificar_prioridade')?'':'none';field('status').style.display=!appointment&&hasPermission('alterar_status')?'':'none';const current=status.value,options=TYPE_STATUS[type];status.innerHTML=options.map(x=>`<option>${x}</option>`).join('');status.value=options.includes(current)?current:options[0];el('newDemandFiles').closest('.field').style.display=''}

function toast(msg){const t=el('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
