show=function(name){if(name==='minhaConta'){openMyAccount();return}if(name==='relatorios'){openReports();return}if(name==='organizacao'){openOrganization();return}if(name!=='usuarios'){showBase(name);return}if(!canManage()){toast('Acesso restrito.');return}document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));el('usuarios').classList.add('active');document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===name));el('title').textContent='Usuários';el('subtitle').textContent='Gerencie perfis, lojas e acessos';el('sidebar').classList.remove('open');el('userEditor').style.display='none';loadUsers()}
async function loadUsers(){if(!canManage())return;el('usersList').innerHTML='<p class="muted">Carregando usuários...</p>';const {data,error}=await db.from('perfis').select('*').order('nome');if(error){el('usersList').innerHTML='<p class="muted">Não foi possível carregar os usuários.</p>';return}el('usersList').innerHTML=`<div style="overflow:auto"><table class="table"><thead><tr><th>Usuário</th><th>Loja/local</th><th>Perfil</th><th>Acesso</th><th></th></tr></thead><tbody>${(data||[]).map(u=>`<tr><td><strong>${esc(u.nome||'Sem nome')}</strong>${u.id===session.user.id?'<small class="muted" style="display:block">Você</small>':''}</td><td><input id="store-${u.id}" value="${esc(u.loja||'')}" placeholder="Nome da loja" style="min-width:160px"></td><td><select id="role-${u.id}" style="min-width:150px">${Object.entries(ROLE_LABELS).map(([value,label])=>`<option value="${value}" ${u.papel===value?'selected':''}>${label}</option>`).join('')}</select></td><td><select id="active-${u.id}"><option value="true" ${u.ativo!==false?'selected':''}>Ativo</option><option value="false" ${u.ativo===false?'selected':''}>Bloqueado</option></select></td><td><button class="edit-button" onclick="saveUserProfile('${u.id}')">Salvar</button></td></tr>`).join('')}</tbody></table></div>`}
async function saveUserProfile(id){if(!canManage())return;const papel=el(`role-${id}`).value,loja=el(`store-${id}`).value.trim(),ativo=el(`active-${id}`).value==='true';if(id===session.user.id&&(!ativo||!['administrador','gestor_manutencao'].includes(papel))&&!confirm('Esta alteração pode retirar seu acesso à gestão. Deseja continuar?'))return;const {error}=await db.from('perfis').update({papel,loja:loja||null,ativo}).eq('id',id);if(error){toast('Não foi possível atualizar: '+error.message);return}toast('Usuário atualizado.');if(id===session.user.id)await loadProfile();await loadUsers()}
const loadUsersBasic=loadUsers;
loadUsers=async function(){if(!canManage())return;el('usersList').innerHTML='<p class="muted">Carregando usuários...</p>';const {data,error}=await db.from('perfis').select('*').order('nome');if(error){el('usersList').innerHTML='<p class="muted">Não foi possível carregar os usuários.</p>';return}el('usersList').innerHTML=`<div style="overflow:auto"><table class="table"><thead><tr><th>Usuário</th><th>Loja/local</th><th>Perfil</th><th>Acesso</th><th>Ações</th></tr></thead><tbody>${(data||[]).map(u=>`<tr><td><strong>${esc(u.nome||'Sem nome')}</strong><small class="muted" style="display:block">${esc(u.email||'')}</small></td><td><input id="store-${u.id}" value="${esc(u.loja||'')}" placeholder="Nome da loja"></td><td><select id="role-${u.id}">${Object.entries(ROLE_LABELS).map(([value,label])=>`<option value="${value}" ${u.papel===value?'selected':''}>${label}</option>`).join('')}</select></td><td><select id="active-${u.id}"><option value="true" ${u.ativo!==false?'selected':''}>Ativo</option><option value="false" ${u.ativo===false?'selected':''}>Bloqueado</option></select></td><td style="white-space:nowrap"><button class="edit-button" onclick="saveUserProfile('${u.id}')">Salvar</button> <button class="link" onclick="sendPasswordReset('${esc(u.email||'')}')">Redefinir senha</button></td></tr>`).join('')}</tbody></table></div>`;if(isAdmin())loadPermissionMatrix()}
async function createManagedUser(e){e.preventDefault();const f=e.target,button=el('createUserButton');button.disabled=true;try{const {data,error}=await db.functions.invoke('admin-users',{body:{action:'create',nome:f.nome.value.trim(),email:f.email.value.trim(),password:f.password.value,papel:f.papel.value,loja:f.loja.value.trim()}});if(error||data?.error)throw new Error(data?.error||error.message);f.reset();toast('Usuário criado com sucesso.');await loadUsers()}catch(error){toast('Não foi possível criar: '+error.message)}finally{button.disabled=false}}
async function sendPasswordReset(email){if(!email){toast('Este usuário ainda não possui e-mail registrado.');return}if(!confirm(`Enviar redefinição de senha para ${email}?`))return;const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});toast(error?'Não foi possível enviar: '+error.message:'E-mail de redefinição enviado.')}
const PERMISSION_LABELS={visualizar_todas:'Visualizar todas as demandas',visualizar_proprias:'Visualizar somente as próprias',criar_corretiva:'Criar demanda corretiva',criar_agendamento:'Criar agendamento de serviço',criar_preventiva:'Criar demanda preventiva/programada',aprovar_agendamento:'Aprovar ou reprovar agendamentos',editar_todas:'Editar qualquer demanda',editar_proprias:'Editar as próprias demandas',classificar_prioridade:'Classificar prioridade',alterar_status:'Alterar status, responsável e prazo',excluir_midia:'Excluir mídia',apagar_demanda:'Apagar demanda',visualizar_historico:'Visualizar histórico',emitir_relatorios:'Emitir relatórios',gerenciar_usuarios:'Gerenciar usuários',gerenciar_permissoes:'Gerenciar permissões'};
async function loadPermissionMatrix(){const {data,error}=await db.from('permissoes_perfis').select('*').eq('organizacao_id',profile.organizacao_id);if(error)return;const map={};(data||[]).forEach(x=>map[`${x.papel}:${x.acao}`]=x.permitido);const roles=['administrador','gestor_manutencao','tecnico','lojista'];el('permissionMatrix').innerHTML=`<div style="overflow:auto"><table class="table permission-table"><thead><tr><th>Ação</th>${roles.map(r=>`<th>${ROLE_LABELS[r]}</th>`).join('')}</tr></thead><tbody>${Object.entries(PERMISSION_LABELS).map(([action,label])=>`<tr><td>${label}</td>${roles.map(r=>`<td style="text-align:center"><input type="checkbox" ${r==='administrador'||map[`${r}:${action}`]?'checked':''} ${r==='administrador'?'disabled':''} onchange="savePermission('${r}','${action}',this.checked)"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
