const startEditBase=startEdit;
startEdit=function(id){startEditBase(id);const d=demands.find(item=>Number(item.id)===Number(id));if(!d)return;const title=el('form').elements.title;if(d.title&&![...title.options].some(option=>option.value===d.title))title.add(new Option(d.title,d.title));title.value=d.title||MAINTENANCE_TYPES[0];refreshDemandTypeOptions();el('demandType').value=d.type||'corretiva';configureDemandType();if(d.scheduledAt){const date=new Date(d.scheduledAt),local=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString();el('scheduleDate').value=d.type==='preventiva'?local.slice(0,10):local.slice(0,16)}else el('scheduleDate').value='';el('companyName').value=d.company||'';el('additionalNotes').value=d.additionalNotes||''}
async function loadData(){const {data,error}=await db.from('demandas').select('*').order('criado_em',{ascending:false});if(error){toast('Não foi possível carregar as demandas.');return}demands=(data||[]).map(d=>({...d,code:d.codigo,type:d.tipo_demanda||'corretiva',scheduledAt:d.agendamento_em,company:d.empresa_prestador,serviceType:d.tipo_servico,additionalNotes:d.observacoes_adicionais,title:d.titulo,category:d.categoria,location:d.local,priority:d.prioridade,deadline:d.prazo,responsible:d.responsavel,next:d.proxima_acao,notes:d.observacoes,createdAt:d.criado_em}));render()}
async function decideAppointment(id,decision){if(!hasPermission('aprovar_agendamento'))return;const verb=decision==='Aprovado'?'aprovar':'reprovar';if(!confirm(`Deseja ${verb} este agendamento?`))return;const {error}=await db.rpc('decidir_agendamento',{p_demanda_id:id,p_decisao:decision});if(error){toast('Não foi possível registrar a decisão: '+error.message);return}await loadData();viewDemand(id);toast(`Agendamento ${decision.toLowerCase()} com sucesso.`)}
function openAppointmentAction(id,mode){el('appointmentActionId').value=id;el('appointmentActionMode').value=mode;el('appointmentActionTitle').textContent=mode==='reagendar'?'Reagendar serviço':'Cancelar agendamento';el('rescheduleField').style.display=mode==='reagendar'?'':'none';el('cancelReasonField').style.display=mode==='cancelar'?'':'none';el('rescheduleDate').value='';el('cancelReason').value='';el('appointmentActionModal').style.display='flex'}
async function confirmAppointmentAction(){const id=Number(el('appointmentActionId').value),mode=el('appointmentActionMode').value,button=el('confirmAppointmentAction');button.disabled=true;try{if(mode==='reagendar'&&!el('rescheduleDate').value)throw new Error('Informe a nova data e horário.');const reason=el('cancelReason').value.trim();if(mode==='cancelar'&&!reason)throw new Error('Informe a justificativa do cancelamento.');const params=mode==='reagendar'?{p_demanda_id:id,p_nova_data:new Date(el('rescheduleDate').value).toISOString()}:{p_demanda_id:id,p_justificativa:reason};const {error}=await db.rpc(mode==='reagendar'?'solicitar_reagendamento':'cancelar_agendamento_lojista',params);if(error)throw error;el('appointmentActionModal').style.display='none';await loadData();viewDemand(id);toast(mode==='reagendar'?'Reagendamento enviado para aprovação.':'Agendamento cancelado.')}catch(error){toast(error.message||'Não foi possível concluir a ação.')}finally{button.disabled=false}}
async function loadProfile(){const {data,error}=await db.from('perfis').select('*').eq('id',session.user.id).maybeSingle();if(error)throw error;profile=data;if(data?.ativo===false){await db.auth.signOut();throw new Error('Seu acesso está bloqueado.')}permissions={};if(data?.papel!=='administrador'){const {data:rules}=await db.from('permissoes_perfis').select('acao,permitido').eq('organizacao_id',data.organizacao_id).eq('papel',data.papel);(rules||[]).forEach(item=>permissions[item.acao]=item.permitido)}const name=data?.nome||session.user.email;el('userName').textContent=name;el('userRole').textContent=ROLE_LABELS[data?.papel]||'Usuário';el('userInitials').textContent=name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();applyRoleVisibility();return profile}
async function migrateLocalDemands(){if(localStorage.getItem('cw-migrated-v1')||!profile?.organizacao_id)return;let local=[];try{local=JSON.parse(localStorage.getItem('cw-demands')||'[]')}catch{}const created=local.filter(d=>Number(d.id)>1000000000000);if(!created.length){localStorage.setItem('cw-migrated-v1','done');return}const rows=created.map(d=>({organizacao_id:profile.organizacao_id,titulo:d.title,categoria:d.category,local:d.location,prioridade:d.priority||'Média',responsavel:d.responsible||null,status:d.status||'A Fazer',prazo:d.deadline||null,proxima_acao:d.next||null,observacoes:d.notes||null,criado_por:session.user.id}));const {error}=await db.from('demandas').insert(rows);if(!error){localStorage.setItem('cw-migrated-v1','done');toast(`${rows.length} demanda(s) antiga(s) recuperada(s).`)}}
async function enterApp(current){session=current;el('authScreen').classList.toggle('hidden',!!session);if(session){await loadProfile();await migrateLocalDemands();await loadData()}else{demands=[];render()}}

async function openReports(){if(!hasPermission('emitir_relatorios')){toast('Acesso restrito.');return}document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));el('relatorios').classList.add('active');document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view==='relatorios'));el('title').textContent='Relatórios';el('subtitle').textContent='Personalize indicadores e exporte PDF ou XLSX';el('sidebar').classList.remove('open');el('organizationSettings').style.display=isAdmin()?'':'none';el('reportPreview').innerHTML='<p class="muted">Carregando informações...</p>';const {data,error}=await db.rpc('dados_relatorio');if(error){el('reportPreview').innerHTML=`<p class="muted">Não foi possível carregar: ${esc(error.message)}</p>`;return}reportCache=data;const o=data.organizacao||{};['Name','Cnpj','Address','Phone','Email'].forEach(key=>{const map={Name:'nome',Cnpj:'cnpj',Address:'endereco',Phone:'telefone',Email:'email'};el('org'+key).value=o[map[key]]||''});const users=[...new Map((data.demandas||[]).map(d=>[d.usuario_id,{id:d.usuario_id,nome:d.usuario_nome,loja:d.loja}])).values()].filter(x=>x.id);el('reportUsers').innerHTML=users.map(u=>`<option value="${u.id}">${esc(u.nome)}${u.loja?' — '+esc(u.loja):''}</option>`).join('');buildReportPreview()}
async function openOrganization(){if(!isAdmin()){toast('Acesso restrito.');return}document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));el('organizacao').classList.add('active');document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view==='organizacao'));el('title').textContent='Organização';el('subtitle').textContent='Cadastre a identidade da empresa';el('sidebar').classList.remove('open');const {data,error}=await db.from('organizacoes').select('*').eq('id',profile.organizacao_id).single();if(error){toast('Não foi possível carregar os dados da organização.');return}reportCache={...(reportCache||{}),organizacao:data};const map={Name:'nome',Cnpj:'cnpj',Address:'endereco',Phone:'telefone',Email:'email'};Object.entries(map).forEach(([key,column])=>el('org'+key).value=data[column]||'')}
function selectedReportRows(){if(!reportCache)return[];const types=[...document.querySelectorAll('[name="report_type"]:checked')].map(x=>x.value),users=[...el('reportUsers').selectedOptions].map(x=>x.value),statuses=[...el('reportStatuses').selectedOptions].map(x=>x.value),start=el('reportStart').value,end=el('reportEnd').value;return(reportCache.demandas||[]).filter(d=>types.includes(d.tipo_demanda)&&(!users.length||users.includes(d.usuario_id))&&(!statuses.length||statuses.includes(d.status))&&(!start||localDay(d.data_cadastro)>=start)&&(!end||localDay(d.data_cadastro)<=end))}
function reportSummary(rows){return{total:rows.length,abertas:rows.filter(d=>open({status:d.status})).length,concluidas:rows.filter(d=>d.status==='Concluído').length,canceladas:rows.filter(d=>d.status==='Cancelado'||d.status==='Reprovado').length}}
function reportStatusSummary(type,rows){return TYPE_STATUS[type].map(status=>({status,total:rows.filter(d=>d.status===status).length}))}
function reportFilterDescription(){const types=[...document.querySelectorAll('[name="report_type"]:checked')].map(x=>DEMAND_TYPES[x.value]),users=[...el('reportUsers').selectedOptions].map(x=>x.textContent),statuses=[...el('reportStatuses').selectedOptions].map(x=>x.value),start=el('reportStart').value,end=el('reportEnd').value;return{tipos:types.length?types.join(', '):'Nenhum',usuarios:users.length?users.join(', '):'Todos',status:statuses.length?statuses.join(', '):'Todos',periodo:start||end?`${start?new Date(start+'T12:00:00').toLocaleDateString('pt-BR'):'Início'} até ${end?new Date(end+'T12:00:00').toLocaleDateString('pt-BR'):'Hoje'}`:'Todo o período'}}
function buildReportPreview(){const rows=selectedReportRows(),m=reportSummary(rows),blocks=Object.entries(DEMAND_TYPES).map(([type,label])=>{const items=rows.filter(d=>d.tipo_demanda===type),statuses=reportStatusSummary(type,items);return`<section style="margin-top:28px"><h2>${label}</h2><p class="muted" style="margin:8px 0 16px"><strong>Total: ${items.length}</strong> &nbsp; ${statuses.map(x=>`${x.status}: ${x.total}`).join(' &nbsp; ')}</p>${table(items.map(d=>({id:d.id,code:d.codigo,title:d.tipo,location:d.local,responsible:d.responsavel||d.prestador,company:d.prestador,deadline:d.prazo,priority:d.prioridade,status:d.status,type:d.tipo_demanda})))}</section>`}).join('');el('reportPreview').innerHTML=`<div class="cards" style="margin-bottom:20px"><article class="card"><small class="muted">Total geral</small><div class="value">${m.total}</div></article><article class="card"><small class="muted">Em aberto</small><div class="value">${m.abertas}</div></article><article class="card done"><small class="muted">Concluídas</small><div class="value">${m.concluidas}</div></article><article class="card danger"><small class="muted">Canceladas/Reprovadas</small><div class="value">${m.canceladas}</div></article></div>${blocks}`}
async function saveOrganizationSettings(e){e.preventDefault();if(!isAdmin())return;const f=e.target,logo=el('orgLogo').files[0],payload={nome:f.nome.value.trim(),cnpj:f.cnpj.value.trim()||null,endereco:f.endereco.value.trim()||null,telefone:f.telefone.value.trim()||null,email:f.email.value.trim()||null};try{if(logo){if(logo.size>5242880)throw new Error('A logo deve ter no máximo 5 MB.');const ext=(logo.name.split('.').pop()||'png').toLowerCase(),path=`${profile.organizacao_id}/logo.${ext}`;const {error}=await db.storage.from('cw-logos').upload(path,logo,{upsert:true,contentType:logo.type});if(error)throw error;payload.logo_path=path}const {error}=await db.from('organizacoes').update(payload).eq('id',profile.organizacao_id);if(error)throw error;toast('Identidade da organização salva.');await openOrganization()}catch(error){toast('Não foi possível salvar: '+error.message)}}
function reportExportRows(rows){return rows.map(d=>({'Código':d.codigo,'Categoria':DEMAND_TYPES[d.tipo_demanda]||d.tipo_demanda,'Tipo':d.tipo,'Local':d.local,'Usuário':d.usuario_nome,'Loja':d.loja||'','Data de cadastro':new Date(d.data_cadastro).toLocaleString('pt-BR'),'Data/Prazo previsto':d.data_prevista?new Date(d.data_prevista).toLocaleString('pt-BR'):(d.prazo||''),'Responsável/Prestador':d.responsavel||d.prestador||'','Prioridade':d.prioridade,'Status':d.status,'Descrição':d.descricao||''}))}
function exportReportXlsx(){const rows=selectedReportRows(),o=reportCache.organizacao||{},m=reportSummary(rows),filters=reportFilterDescription(),wb=XLSX.utils.book_new(),summary=[['RELATÓRIO DE MANUTENÇÃO'],[o.nome||'Organização'],['CNPJ',o.cnpj||''],['Endereço',o.endereco||''],['Contato',[o.telefone,o.email].filter(Boolean).join(' • ')],['Emitido por',reportCache.solicitante?.nome||''],['Emissão',new Date().toLocaleString('pt-BR')],[],['FILTROS APLICADOS'],['Tipos de demanda',filters.tipos],['Usuários/lojas',filters.usuarios],['Status',filters.status],['Período',filters.periodo],[],['INDICADORES GERAIS'],['Total',m.total],['Em aberto',m.abertas],['Concluídas',m.concluidas],['Canceladas/Reprovadas',m.canceladas],[],['Sistema desenvolvido por CW Engenharia e Soluções']];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(summary),'Resumo');Object.entries(DEMAND_TYPES).forEach(([type,label])=>{const items=rows.filter(d=>d.tipo_demanda===type),statuses=reportStatusSummary(type,items),sheetName=label.replace('Demanda ','').replace(/[\\/?*\[\]:]/g,'-').slice(0,31),statusRow=['Total',items.length];statuses.forEach(x=>statusRow.push(x.status,x.total));const sheet=XLSX.utils.aoa_to_sheet([[label],statusRow,[]]);XLSX.utils.sheet_add_json(sheet,reportExportRows(items),{origin:'A4'});XLSX.utils.book_append_sheet(wb,sheet,sheetName)});XLSX.writeFile(wb,`relatorio-manutencao-${today()}.xlsx`)}
async function logoDataUrl(){const path=reportCache?.organizacao?.logo_path;if(!path)return null;const {data}=await db.storage.from('cw-logos').createSignedUrl(path,300);if(!data?.signedUrl)return null;const blob=await fetch(data.signedUrl).then(r=>r.blob());return await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(blob)})}
async function exportReportPdf(){const rows=selectedReportRows(),o=reportCache.organizacao||{},m=reportSummary(rows),filters=reportFilterDescription(),{jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape'}),logo=await logoDataUrl(),footer=()=>{doc.setFontSize(8);doc.setTextColor(100);doc.text('Sistema desenvolvido por CW Engenharia e Soluções',15,doc.internal.pageSize.height-8)},header=()=>{if(logo)try{doc.addImage(logo,15,12,28,20)}catch{}doc.setTextColor(20);doc.setFontSize(16);doc.text(o.nome||'Relatório de Manutenção',logo?48:15,18);doc.setFontSize(9);doc.text([o.cnpj&&`CNPJ: ${o.cnpj}`,o.endereco,[o.telefone,o.email].filter(Boolean).join(' • ')].filter(Boolean),logo?48:15,24)};header();doc.setFontSize(10);doc.text(`Geral — Total: ${m.total}   Em aberto: ${m.abertas}   Concluídas: ${m.concluidas}   Canceladas/Reprovadas: ${m.canceladas}`,15,40);doc.setFontSize(9);doc.setFont(undefined,'bold');doc.text('Filtros aplicados',15,48);doc.setFont(undefined,'normal');const filterLines=[`Tipos de demanda: ${filters.tipos}`,`Usuários/lojas: ${filters.usuarios}`,`Status: ${filters.status}`,`Período: ${filters.periodo}`].flatMap(line=>doc.splitTextToSize(line,265));doc.text(filterLines,15,54);const firstBlockY=59+filterLines.length*4;Object.entries(DEMAND_TYPES).forEach(([type,label],index)=>{if(index){doc.addPage();header()}const titleY=index?42:firstBlockY,items=rows.filter(d=>d.tipo_demanda===type),statuses=reportStatusSummary(type,items),statusLines=doc.splitTextToSize(`Total: ${items.length}   ${statuses.map(x=>`${x.status}: ${x.total}`).join('   ')}`,265);doc.setFontSize(12);doc.setTextColor(20);doc.text(label,15,titleY);doc.setFontSize(9);doc.text(statusLines,15,titleY+5);doc.autoTable({startY:titleY+5+statusLines.length*4,head:[['Código','Tipo','Local','Usuário','Cadastro','Responsável/Prestador','Prioridade','Status']],body:items.map(d=>[d.codigo,d.tipo,d.local,d.usuario_nome,new Date(d.data_cadastro).toLocaleDateString('pt-BR'),d.responsavel||d.prestador||'—',d.prioridade,d.status]),styles:{fontSize:7},headStyles:{fillColor:[11,31,58]},didDrawPage:footer})});doc.save(`relatorio-manutencao-${today()}.pdf`)}

