el('form').onsubmit=async e=>{e.preventDefault();const button=el('saveDemand'),isEditing=editingId!==null,files=[...el('newDemandFiles').files];if(button.disabled)return;button.disabled=true;button.textContent=files.length?'Salvando e enviando arquivos...':'Salvando...';try{if(!session)throw new Error('Sua sessão expirou. Entre novamente.');if(!profile)await loadProfile();if(!profile?.organizacao_id)throw new Error('Seu perfil ainda não está vinculado ao Serena Mall.');const x=Object.fromEntries(new FormData(e.target)),store=isStore(),type=x.demand_type,scheduled=['agendamento','preventiva'].includes(type);if(!x.title?.trim())throw new Error('Selecione o tipo de manutenção.');if(!x.location?.trim())throw new Error('Informe o local.');if(type==='corretiva'&&!x.notes?.trim())throw new Error('Descreva o problema.');if(scheduled&&!x.schedule_date)throw new Error(type==='agendamento'?'Informe a data e o horário previstos.':'Informe a data prevista.');if(scheduled&&!x.company_name?.trim())throw new Error(type==='agendamento'?'Informe o prestador.':'Informe o responsável pela execução.');const schedule=scheduled?new Date(x.schedule_date).toISOString():null,defaultStatus={corretiva:'Registrado',agendamento:'Aguardando aprovação',preventiva:'Agendado'}[type];if(!isEditing&&!hasPermission(`criar_${type}`))throw new Error('Seu perfil não possui permissão para criar este tipo de demanda.');const payload={organizacao_id:profile.organizacao_id,titulo:x.title.trim(),categoria:'Manutenção',local:x.location.trim(),prioridade:type==='corretiva'&&!store?x.priority:'A definir',responsavel:type==='corretiva'?(x.responsible||null):null,status:isEditing?x.status:defaultStatus,prazo:type==='corretiva'?(x.deadline||null):null,proxima_acao:null,observacoes:(x.notes||'').trim(),observacoes_adicionais:type==='preventiva'?(x.additional_notes||'').trim()||null:null,tipo_demanda:type,agendamento_em:schedule,empresa_prestador:scheduled?x.company_name.trim():null,tipo_servico:x.title.trim()};const result=isEditing?await db.from('demandas').update(payload).eq('id',editingId).select('id').single():await db.rpc('criar_demanda_usuario',{p_titulo:payload.titulo,p_local:payload.local,p_observacoes:payload.observacoes,p_tipo_demanda:type,p_agendamento_em:schedule,p_empresa_prestador:payload.empresa_prestador,p_prioridade:payload.prioridade,p_responsavel:payload.responsavel,p_prazo:payload.prazo,p_observacoes_adicionais:payload.observacoes_adicionais});const {data,error}=result;if(error)throw error;if(!data)throw new Error('O Supabase não confirmou a operação.');const savedId=data.id;let mediaError=null;if(files.length){try{await uploadDemandFiles(savedId,files)}catch(error){mediaError=error}}cancelEdit();await loadData();viewDemand(savedId);toast(mediaError?'Demanda salva, mas alguns arquivos falharam: '+mediaError.message:(isEditing?'Demanda atualizada com sucesso.':'Demanda cadastrada com sucesso.'))}catch(error){console.error(error);toast('Não foi possível salvar: '+(error.message||'tente novamente.'))}finally{button.disabled=false;button.textContent=editingId!==null?'Salvar alterações':'Cadastrar demanda'}}
