el('deleteDemandButton').onclick=async()=>{const id=editingId;if(!id||!hasPermission('apagar_demanda'))return;if(!confirm('Excluir esta demanda permanentemente? O histórico e as mídias também serão removidos.'))return;const {data:attachments}=await db.from('anexos_demandas').select('storage_path').eq('demanda_id',id),paths=(attachments||[]).map(x=>x.storage_path);if(paths.length){const {error:storageError}=await db.storage.from('cw-anexos').remove(paths);if(storageError){toast('Não foi possível excluir as mídias da demanda.');return}}const {error}=await db.from('demandas').delete().eq('id',id);if(error){toast('Não foi possível excluir: '+error.message);return}cancelEdit();applyRoleVisibility();await loadData();show('demandas');toast('Demanda excluída.')};
