el('uploadAttachments').onclick=async()=>{const files=[...el('attachmentFiles').files],description=el('attachmentDescription').value.trim(),button=el('uploadAttachments');if(!editingId)return;if(!files.length){toast('Selecione pelo menos um arquivo.');return}button.disabled=true;el('uploadStatus').textContent=`Enviando 0 de ${files.length}...`;let completed=0;try{for(const file of files){if(file.size>52428800)throw new Error(`${file.name} ultrapassa 50 MB.`);const safe=file.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${editingId}/${crypto.randomUUID()}-${safe}`;const {error:uploadError}=await db.storage.from('cw-anexos').upload(path,file,{contentType:file.type,upsert:false});if(uploadError)throw uploadError;const {error:recordError}=await db.from('anexos_demandas').insert({demanda_id:editingId,storage_path:path,nome_arquivo:file.name,tipo_arquivo:file.type,tamanho_bytes:file.size,descricao:description||null,criado_por:session.user.id,usuario_nome:profile?.nome||session.user.email});if(recordError){await db.storage.from('cw-anexos').remove([path]);throw recordError}completed++;el('uploadStatus').textContent=`Enviando ${completed} de ${files.length}...`}el('attachmentFiles').value='';el('attachmentDescription').value='';el('uploadStatus').textContent='Envio concluído.';toast('Anexos enviados com sucesso.');await loadAttachments(editingId)}catch(error){console.error(error);el('uploadStatus').textContent='Falha no envio.';toast('Não foi possível enviar: '+error.message)}finally{button.disabled=false}};
